  KEY `idx_erp_invoices_date_stat_ttn` (`invoice_date`,`stat_ttn`),
  KEY `idx_erp_invoices_date_stat_api` (`invoice_date`,`stat_api`),
  KEY `fk_invoice_user` (`user_id`),
