  PRIMARY KEY (`id`),
  KEY `idx_expense_notes_user_date` (`user_id`,`expense_date`),
  KEY `idx_expense_notes_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=102 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


