DROP TABLE IF EXISTS `purchase_orders`;
CREATE TABLE `purchase_orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `owner_id` int(11) NOT NULL,
  `client_user_id` int(11) NOT NULL,
  `po_number` varchar(191) NOT NULL,
