  `total_tva` decimal(20,3) NOT NULL DEFAULT 0.000,
  `total_ttc` decimal(20,3) NOT NULL DEFAULT 0.000,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_po_owner_number` (`owner_id`,`po_number`),
  KEY `idx_po_owner_client_created` (`owner_id`,`client_user_id`,`created_at`),
  KEY `idx_po_owner_client_status` (`owner_id`,`client_user_id`,`status`),
  KEY `idx_po_hash` (`owner_id`,`client_user_id`,`payload_hash`),
  KEY `fk_po_client` (`client_user_id`),
  CONSTRAINT `fk_po_client` FOREIGN KEY (`client_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_po_owner` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


